import java.util.Calendar;
import java.util.Locale;
import java.util.TimeZone;

public class Calc {
    public static void main(String[] args) {
        Calendar c = Calendar.getInstance(TimeZone.getTimeZone("UTC"), Locale.US);
        c.clear();
        c.set(2023, Calendar.JUNE, 15, 14, 5, 9);
        c.set(Calendar.MILLISECOND, 123);
        System.out.println("WEEK_OF_YEAR=" + c.get(Calendar.WEEK_OF_YEAR));
        System.out.println("WEEK_OF_MONTH=" + c.get(Calendar.WEEK_OF_MONTH));
        System.out.println("DAY_OF_WEEK_IN_MONTH=" + c.get(Calendar.DAY_OF_WEEK_IN_MONTH));
        System.out.println("DAY_OF_YEAR=" + c.get(Calendar.DAY_OF_YEAR));
        System.out.println("isWeekDateSupported=" + c.isWeekDateSupported());
        System.out.println("WeekYear=" + c.getWeekYear());
        System.out.println("HOUR=" + c.get(Calendar.HOUR));
        System.out.println("HOUR_OF_DAY=" + c.get(Calendar.HOUR_OF_DAY));

        Calendar midnight = Calendar.getInstance(TimeZone.getTimeZone("UTC"), Locale.US);
        midnight.clear();
        midnight.set(2023, Calendar.JUNE, 15, 0, 0, 0);
        System.out.println("midnight HOUR=" + midnight.get(Calendar.HOUR));
        System.out.println("midnight HOUR_OF_DAY=" + midnight.get(Calendar.HOUR_OF_DAY));

        Calendar noon = Calendar.getInstance(TimeZone.getTimeZone("UTC"), Locale.US);
        noon.clear();
        noon.set(2023, Calendar.JUNE, 15, 12, 0, 0);
        System.out.println("noon HOUR=" + noon.get(Calendar.HOUR));
        System.out.println("noon HOUR_OF_DAY=" + noon.get(Calendar.HOUR_OF_DAY));

        Calendar jan1 = Calendar.getInstance(TimeZone.getTimeZone("UTC"), Locale.US);
        jan1.clear();
        jan1.set(2023, Calendar.JANUARY, 1, 0, 0, 0);
        System.out.println("jan1 WeekYear=" + jan1.getWeekYear());
        System.out.println("jan1 YEAR=" + jan1.get(Calendar.YEAR));
    }
}
